// Independent original HEADS seed-template search observer; no native outputs.
// Scope: raw black/void template matches on the 11 staff pitches, before
// competitor/bar veto, glyph retrieval, duplicate purge and HeadInter registration.
import org.audiveris.omr.sheet.Book;
import java.util.*;import java.nio.file.*;import java.awt.*;import java.awt.geom.*;import java.lang.reflect.*;import java.security.*;
public class HeadSeedSearchProbe extends LedgerRegistrationControlProbe {
 public HeadSeedSearchProbe(Book b,SortedSet<Integer> ids){super(b,ids);}
 static Object call(Object target,String name,Object...args)throws Exception{for(Class<?> c=target.getClass();c!=null;c=c.getSuperclass())for(Method m:c.getDeclaredMethods())if(m.getName().equals(name)&&m.getParameterCount()==args.length){m.setAccessible(true);try{return m.invoke(target,args);}catch(IllegalArgumentException e){}}throw new NoSuchMethodException(name);}
 static Object staticCall(String c,String n,Object...a)throws Exception{for(Method m:Class.forName("org.audiveris.omr."+c).getMethods())if(m.getName().equals(n)&&m.getParameterCount()==a.length)return m.invoke(null,a);throw new NoSuchMethodException(n);}
 String hash(byte[] a)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(a));}
 String match(Object table,Object catalog,int x0,int y0,int[] xo,int[] yo,String an,String sh)throws Exception{
  Object a=Class.forName("org.audiveris.omr.image.Anchored$Anchor").getField(an).get(null),shape=Class.forName("org.audiveris.omr.glyph.Shape").getField(sh).get(null),t=call(catalog,"getTemplate",shape);double low=(Double)staticCall("image.Template","maxDistanceLow"),bad=(Double)staticCall("image.Template","reallyBadDistance");Double best=null;int bx=0,by=0;
  outer:for(int dy:yo)for(int dx:xo){int x=x0+dx,y=y0+dy;double d=(Double)call(t,"evaluate",x,y,a,table);if(d<=low){if(best==null||best>d){best=d;bx=x;by=y;}}else if(x==x0&&y==y0&&d>=bad)break outer;}
  if(best==null)return "null";String selected=sh;if(sh.equals("NOTEHEAD_BLACK")){Object v=call(catalog,"getTemplate",Class.forName("org.audiveris.omr.glyph.Shape").getField("NOTEHEAD_VOID").get(null));if((Double)call(v,"evaluateHole",bx,by,a,table)>=.2)selected="NOTEHEAD_VOID";}
  Object selectedT=call(catalog,"getTemplate",Class.forName("org.audiveris.omr.glyph.Shape").getField(selected).get(null));double grade=((Number)call(make("sig.inter.HeadInter$Impacts",staticCall("image.Template","impactOf",best)),"getGrade")).doubleValue();
  return "{\"shape\":\""+selected+"\",\"source_shape\":\""+sh+"\",\"anchor\":\""+an+"\",\"x\":"+bx+",\"y\":"+by+",\"score\":"+best+",\"grade\":"+grade+",\"bounds\":"+rect(call(selectedT,"getSlimBoundsAt",bx,by,a))+"}";
 }
 public void process(){try{
  sheet=call(((java.util.List<?>)call(book,"getStubs")).get(0),"getSheet");for(String step:new String[]{"sheet.grid.GridStep","sheet.header.HeadersStep","sheet.stem.StemSeedsStep","sheet.beam.BeamsStep","sheet.ledger.LedgersStep"})call(make(step),"doit",sheet);
  horizontal=Class.forName("org.audiveris.omr.run.Orientation").getField("HORIZONTAL").get(null);vertical=Class.forName("org.audiveris.omr.run.Orientation").getField("VERTICAL").get(null);
  Object table=call(make("sheet.note.DistancesBuilder",sheet),"buildDistances");int w=(Integer)call(table,"getWidth"),h=(Integer)call(table,"getHeight");MessageDigest digest=MessageDigest.getInstance("SHA-256");byte[]mask=new byte[w*h];Arrays.fill(mask,(byte)255);for(int i=0;i<mask.length;i++){int v=(Integer)call(table,"getValue",i);digest.update((byte)(v>>>8));digest.update((byte)v);if(v==-1)mask[i]=0;}
  String distanceHash=HexFormat.of().formatHex(digest.digest()),maskHash=hash(mask);java.awt.image.BufferedImage mi=new java.awt.image.BufferedImage(w,h,java.awt.image.BufferedImage.TYPE_BYTE_GRAY);mi.getRaster().setDataElements(0,0,w,h,mask);javax.imageio.ImageIO.write(mi,"PNG",Path.of(System.getProperty("native.probe.output")).resolveSibling("official-heads-mask.png").toFile());Object family=Class.forName("org.audiveris.omr.ui.symbol.MusicFamily").getField("Bravura").get(null),factory=staticCall("image.TemplateFactory","getInstance"),group=Class.forName("org.audiveris.omr.glyph.GlyphGroup").getField("VERTICAL_SEED").get(null);java.util.List<String>systems=new ArrayList<>(),controls=new ArrayList<>();Object catalog51=call(factory,"getCatalog",family,51);
  for(Object sys:(java.util.List<?>)call(sheet,"getSystems")){java.util.List<?> seeds=(java.util.List<?>)call(sys,"getGroupedGlyphs",group);java.util.List<String>staffs=new ArrayList<>();Object b=make("sheet.note.NoteHeadsBuilder",sys,table,new ArrayList<>(),make("sheet.note.HeadSeedTally"),Boolean.FALSE,new TreeMap<>());setField(b,"systemBarAreas",new ArrayList<>());setField(b,"systemCompetitors",new ArrayList<>());int[]xo=(int[])get(b,"xOffsets");
   for(Object staff:(java.util.List<?>)call(sys,"getStaves")){int size=(Integer)call(staff,"getHeadPointSize");Object catalog=call(factory,"getCatalog",family,size);setField(b,"catalog",catalog);java.util.List<?>ls=(java.util.List<?>)call(staff,"getLines");java.util.List<String>scanners=new ArrayList<>();Object previous=null;int pitch=-5;
    for(int li=0;li<ls.size();li++){Object adapter=make("sheet.note.NoteHeadsBuilder$StaffLineAdapter",b,staff,ls.get(li));for(int dir:li==4?new int[]{-1,0,1}:new int[]{-1,0}){Object second=dir==-1?previous:null;Object scanner=make("sheet.note.NoteHeadsBuilder$Scanner",b,adapter,second,dir,pitch,true);int[]yo=(int[])get(scanner,"yOffsets");Object area=get(scanner,"seedsArea");java.util.List<?> selected=(java.util.List<?>)call(b,"getGlyphsSlice",seeds,area);java.util.List<String>seedCases=new ArrayList<>();
     for(Object seed:selected){Point2D center=(Point2D)call(seed,"getCenter2D"),a=(Point2D)call(seed,"getStartPoint",vertical),z=(Point2D)call(seed,"getStopPoint",vertical);int rough=(int)Math.rint(center.getX());double yl=(Double)call(adapter,"yAt",(double)rough);int x0=(int)Math.rint(a.getX()+(z.getX()-a.getX())*(yl-a.getY())/(z.getY()-a.getY()));int y0=(Integer)call(scanner,"getTheoreticalOrdinate",x0);java.util.List<String>ms=new ArrayList<>();for(String an:new String[]{"LEFT_STEM","RIGHT_STEM"})for(String sh:new String[]{"NOTEHEAD_BLACK","NOTEHEAD_VOID"}){String m=match(table,catalog,x0,y0,xo,yo,an,sh);if(!m.equals("null"))ms.add(m);}seedCases.add("{\"seed\":"+glyph(seed)+",\"x0\":"+x0+",\"y0\":"+y0+",\"matches\":["+String.join(",",ms)+"]}");}
     scanners.add("{\"line_index\":"+li+",\"dir\":"+dir+",\"pitch\":"+pitch+",\"x_offsets\":"+Arrays.toString(xo)+",\"y_offsets\":"+Arrays.toString(yo)+",\"seeds\":["+String.join(",",seedCases)+"]}");pitch++;}previous=adapter;}
    staffs.add("{\"staff_id\":"+call(staff,"getId")+",\"point_size\":"+size+",\"scanners\":["+String.join(",",scanners)+"]}");}
   systems.add("{\"system_id\":"+call(sys,"getId")+",\"staffs\":["+String.join(",",staffs)+"]}");}
  // Original template math and original search-order decision controls on real
  // distance pixels; includes accepted, rejected and noncentral search starts.
  for(int x:new int[]{200,386,578,700,978,1175})for(int y:new int[]{423,534,622,901})for(String an:new String[]{"LEFT_STEM","RIGHT_STEM"}){int[]xo={0,1,-1,2,-2},yo={0,-1,1};java.util.List<String> ms=new ArrayList<>();for(String sh:new String[]{"NOTEHEAD_BLACK","NOTEHEAD_VOID"}){String m=match(table,catalog51,x,y,xo,yo,an,sh);if(!m.equals("null"))ms.add(m);}controls.add("{\"x0\":"+x+",\"y0\":"+y+",\"x_offsets\":"+Arrays.toString(xo)+",\"y_offsets\":"+Arrays.toString(yo)+",\"anchor\":\""+an+"\",\"matches\":["+String.join(",",ms)+"]}");}
  Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"native_outputs_used\":false,\"width\":"+w+",\"height\":"+h+",\"distance_sha256_be_i16\":\""+distanceHash+"\",\"mask_sha256\":\""+maskHash+"\",\"max_distance_low\":"+staticCall("image.Template","maxDistanceLow")+",\"max_distance_high\":"+staticCall("image.Template","maxDistanceHigh")+",\"really_bad_distance\":"+staticCall("image.Template","reallyBadDistance")+",\"systems\":["+String.join(",",systems)+"],\"controls\":["+String.join(",",controls)+"],\"scope\":\"Original in-memory GRID through LEDGERS and DistancesBuilder; original Scanner seed-area selection, theoretical ordinates and offsets; original Template evaluation and hole conversion before competitor/bar veto, glyph retrieval or registration. Staff pitches -5..5, Bravura black/void only.\"}\n");
 }catch(Exception e){throw new RuntimeException(e);}}
}
